from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import DhcpconfdURI


class DhcpconfdV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_dhcp_network_interfaces(self, timeout=60):
        uri = DhcpconfdURI().dhcp_network_interface_uri
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def get_dhcp_subnets(self, subnet_type='ipv4', timeout=60):
        uri = DhcpconfdURI().dhcp_subnet_uri
        params = {'subnet_type': subnet_type}
        return self.api_client.send_get_request(uri=uri, params=params, timeout=timeout)

    def create_new_subnet(self, subnet_type='ipv4', timeout=60, **kwargs):
        uri = DhcpconfdURI().dhcp_subnet_uri
        headers = {'Subnet-Type': subnet_type}
        return self.api_client.send_post_request(uri=uri, headers=headers, json=kwargs,
                                                 timeout=timeout)['id']

    def delete_dhcp_subnet(self, subnet_id, subnet_type='ipv4', timeout=60):
        uri = DhcpconfdURI().dhcp_subnet_uri + f"/id/{subnet_id}"
        headers = {'Subnet-Type': subnet_type}
        return self.api_client.send_delete_request(uri=uri, headers=headers, timeout=timeout)

    def get_dhcp_global_config(self, timeout=60):
        uri = DhcpconfdURI().dhcp_global_config_uri
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def modify_dhcp_global_config(self, timeout=60, **kwargs):
        uri = DhcpconfdURI().dhcp_global_config_uri
        return self.api_client.send_put_request(uri=uri, json=kwargs, timeout=timeout)


